const body = $input.first().json.body || $input.first().json;
const vendors = body.vendors || [];
if (!vendors.length) return [{ json: { _no_vendors: true } }];
return vendors.map(v => ({
  json: {
    vendor_name: v.vendor_name || v.name || '',
    website: (v.website || '').replace(/\/$/, ''),
    _needs_founded: !v.founded,
    _needs_hq: !v.hq_address,
    _needs_funding_stage: !v.funding_stage,
    _needs_total_funding: !v.total_funding,
    apify_token: body.apify_token || '',
  }
}));

const item = $input.first().json;
function deriveSlug(name, website) {
  if (website) {
    const domain = website.replace(/^https?:\/\/(?:www\.)?/, '').split('/')[0];
    const base = domain.split('.')[0];
    if (base && base.length >= 3) return base.toLowerCase();
  }
  return name.toLowerCase().replace(/[^a-z0-9 ]/g, '').trim().replace(/ +/g, '-');
}
const slug = deriveSlug(item.vendor_name, item.website);
return [{ json: { ...item, tracxn_slug: slug, tracxn_url: `https://tracxn.com/d/companies/${slug}/` } }];

const vendor = $('Derive Slug').first().json;
const crawl = $input.first().json;
const pages = crawl.pages || [];
const page = pages[0] || {};
const text = String(page.text || page.text_excerpt || '');
const html = String(page.html || '');
const wordCount = text.split(/\s+/).filter(w => w.length > 1).length;
const isReachable = wordCount >= 100;
return [{
  json: {
    vendor_name: vendor.vendor_name,
    website: vendor.website,
    tracxn_slug: vendor.tracxn_slug,
    tracxn_url: vendor.tracxn_url,
    _needs_founded: vendor._needs_founded,
    _needs_hq: vendor._needs_hq,
    _needs_funding_stage: vendor._needs_funding_stage,
    _needs_total_funding: vendor._needs_total_funding,
    page_valid: isReachable,
    visible_text: isReachable ? text.slice(0, 10000) : '',
    raw_html: isReachable ? html.slice(0, 50000) : '',
    word_count: wordCount,
  }
}];

const item = $input.first().json;
const text = item.visible_text || '';
const html = item.raw_html || '';

// Founded year
const foundedMatch = text.match(/\b((?:19|20)\d{2})\b/);
const founded = foundedMatch ? foundedMatch[1] : null;

// HQ — JSON-LD first, then text heuristic
let hq_address = null;
const ldMatches = [...html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
for (const m of ldMatches) {
  try {
    const data = JSON.parse(m[1]);
    const addr = data.address || {};
    if (typeof addr === 'object') {
      const parts = [addr.addressLocality, addr.addressRegion, addr.addressCountry].filter(Boolean);
      if (parts.length) { hq_address = parts.join(', '); break; }
    }
  } catch(e) {}
}
if (!hq_address) {
  const hqMatch = text.match(/(?:Headquarters|HQ)[:\s]+([A-Z][^\n,;|]{3,50})/);
  if (hqMatch) hq_address = hqMatch[1].trim();
}

// Funding stage
const stageMatch = text.match(/Series\s+[A-Z]{1,2}|Pre-Seed|Seed(?:\s+Round)?|IPO|Acquired|Private Equity|Growth|Bootstrapped|Angel/i);
const funding_stage = stageMatch ? stageMatch[0].trim() : null;

// Total funding
const fundingMatch = text.match(/\$[\d.,]+\s*[BMKbmk]/);
const total_funding = fundingMatch ? fundingMatch[0].trim() : null;

// Safe-upsert: only include fields that were empty and Tracxn found
const payload = { vendor_name: item.vendor_name, website: item.website };
if (item._needs_founded && founded) payload.founded = founded;
if (item._needs_hq && hq_address) payload.hq_address = hq_address;
if (item._needs_funding_stage && funding_stage) payload.funding_stage = funding_stage;
if (item._needs_total_funding && total_funding) payload.total_funding = total_funding;

const fieldsFound = Object.keys(payload).filter(k => !['vendor_name','website'].includes(k));
return [{ json: { ...payload, tracxn_url: item.tracxn_url, _has_data: fieldsFound.length > 0, _fields_found: fieldsFound } }];
